  from jsonb_to_recordset($j$[{"topic":"math","band":"c6-8","difficulty":1,"q":"১৫০-এর ১০% কত?","options":["১৫০","৩০","২৫","১৫"],"answer_idx":3,"explanation":"১৫০ × ১০ ÷ ১০০ = ১৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"১৫-এর বর্গ কত?","options":["৩০","২২৫","২১০","২৪০"],"answer_idx":1,"explanation":"১৫² = ১৫ × ১৫ = ২২৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"√২৫৬ = কত?","options":["১৫","১৭","১৬","৩২"],"answer_idx":2,"explanation":"১৬ × ১৬ = ২৫৬, তাই বর্গমূল ১৬।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"x + ২০ = ৪১ হলে x = কত?","options":["২১","২২","৬১","২০"],"answer_idx":0,"explanation":"x = ৪১ − ২০ = ২১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৪x + ৮ = ৬৮ হলে x = কত?","options":["৬০","১৬","১৫","১৯"],"answer_idx":2,"explanation":"৪x = ৬৮ − ৮ = ৬০, তাই x = ৬০ ÷ ৪ = ১৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"২৫, ২৪, ৪৫, ৩৩, ৭৮ — এই সংখ্যাগুলোর গড় কত?","options":["৩৯","৪৩","২০৫","৪১"],"answer_idx":3,"explanation":"যোগফল = ২০৫, সংখ্যা ৫টা, গড় = ২০৫ ÷ ৫ = ৪১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"দুইজনের টাকার অনুপাত ৮ : ৬। মোট ৭০ টাকা হলে প্রথমজনের অংশ কত টাকা?","options":["৬২","৪০","৪৮","৩০"],"answer_idx":1,"explanation":"মোট ভাগ = ৮ + ৬ = ১৪। এক ভাগ = ৭০ ÷ ১৪ = ৫। প্রথমজন = ৫ × ৮ = ৪০ টাকা।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৩০০০ টাকার ৪% সরল হারে ২ বছরের মুনাফা কত টাকা?","options":["২৭০","২৪০","২৪০০","১২০"],"answer_idx":1,"explanation":"মুনাফা = (৩০০০ × ৪ × ২) ÷ ১০০ = ২৪০ টাকা।","source":"গণিতের